import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class SecureLoginServlet extends HttpServlet {
    private static final String DB_URL = "jdbc:mysql://localhost:3306/appdb";

    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String id = req.getParameter("id");
        String password = req.getParameter("password");

        // 수정: PreparedStatement와 파라미터 바인딩을 사용하여 SQL 인젝션을 방지
        String sql = "SELECT * FROM users WHERE id = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection(DB_URL, "user", "password");
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, id);
            pstmt.setString(2, password);

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    resp.getWriter().println("로그인 성공");
                } else {
                    resp.getWriter().println("로그인 실패");
                }
            }
        }
    }
}

